    }
    if let Some(t) = self.scan_number().map(Ok) {
        return t;
    }
    if let Some(t) = self.scan_string()? {
        return Ok(Some(t));
    }
    if let Some(t) = self.scan_symbol().map(Ok) {
        return t;
    }
    Err(errinput!("unexpected character"))
}

